{"content":"// Package cli parses the command line of the frob tool.
package cli

import (
	"errors"
	"fmt"
	"strconv"
)

// ErrUsage is wrapped by every parse error.
var ErrUsage = errors.New("usage error")

// Config is the parsed command line.
type Config struct {
	Verbose bool
	Count   int
	Output  string
	Tags    []string
	Args    []string
}

// Parse parses the command line arguments.
func Parse(args []string) (Config, error) {
	var c Config
	c.Count = 1
	c.Output = "-"

	var usageErr func(string) error = func(format string, a ...any) error {
		return fmt.Errorf("%w: %s", ErrUsage, fmt.Sprintf(format, a...))
	}

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			for _, rest := range args[i+1:] {
				c.Args = append(c.Args, rest)
			}
			break
		}
		if arg == "-" {
			c.Args = append(c.Args, arg)
			continue
		}
		if len(arg) > 1 && arg[0] == '-' {
			name := arg
			value := ""
			hasValue := false
			if strings_hasPrefix(name, "--") {
				// Long flag.
				body := name[2:]
				if eq := indexByte(body, '='); eq >= 0 {
					name = name[:2+eq]
					value = body[eq+1:]
					hasValue = true
				}
			} else {
				// Short flags, possibly combined.
				body := arg[1:]
				switch {
				case len(body) > 0 && body[0] == '=':
					name = "-" + string(body[0])
					value = body[1:]
					hasValue = true
				case len(body) == 1:
					name = arg
				default:
					// Combined short flags like -vv: first letter is the
					// flag, the rest is its value.
					if body[0] == 'v' {
						for _, r := range body {
							c.Verbose = true
						}
						continue
					}
					if body[0] == 'n' || body[0] == 'o' {
						name = "-" + string(body[0])
						value = body[1:]
						hasValue = true
					}
				}
			}
			if !hasValue {
				if i+1 < len(args) {
					i++
					value = args[i]
				}
			}
			switch {
			case name == "-v" || name == "--verbose":
				c.Verbose = true
				if hasValue && value != "" {
					return c, usageErr("flag -v does not take an argument")
				}
			case name == "-n" || name == "--count":
				n, err := strconv.Atoi(value)
				if err != nil || n < 0 {
					return c, usageErr("invalid value %q for %s: must be an integer >= 0", value, name)
				}
				c.Count = n
			case name == "-o" || name == "--output":
				if !hasValue {
					return c, usageErr("flag -o requires an argument")
				}
				c.Output = value
			case name == "--tag":
				c.Tags = append(c.Tags, value)
			default:
				return c, usageErr("unknown flag %s", name)
			}
			continue
		}
		c.Args = append(c.Args, arg)
	}
	return c, nil
}

// hasPrefix reports whether s has the given prefix.
func strings_hasPrefix(s, prefix string) bool {
	return len(s) >= len(prefix) && s[:len(prefix)] == prefix
}

// indexByte returns the index of the first occurrence of c in s, or -1.
func indexByte(s string, c byte) int {
	for i := 0; i < len(s); i++ {
		if s[i] == c {
			return i
		}
	}
	return -1
}

var _ = errors.New // keep errors import if usage changes
